def encoding_of(value):
    try:
        iv = int(value)
        if str(iv) == value and -(2 ** 63) <= iv < 2 ** 63:
            return "int"
    except ValueError:
        pass
    if len(value.encode("utf-8")) <= 44:
        return "embstr"
    return "raw"

cases = ["123", "hello", "x" * 44, "x" * 45, "99999999999999999999"]
for v in cases:
    print("%-22s -> %s" % (repr(v[:20]), encoding_of(v)))
